/**
 * Editorial translations are tied to the exact English strings of a reviewed
 * update. A changed English review deliberately falls back to its original
 * rather than silently displaying an outdated, potentially unsafe translation.
 */
type AuditField = 'verdict' | 'auditSummary' | 'listedDomainWarning' | 'legalSummary';
type FirmAuditTranslation = Partial<Record<AuditField, string>>;
type AuditLocale = Partial<Record<string, FirmAuditTranslation>>;
type AuditSource = {
  set?: Partial<Record<Exclude<AuditField, 'legalSummary'>, string | null>>;
  setLegalReview?: { summary?: string; regulatoryStatus?: string[]; complaintsAndDisputes?: string[]; redFlags?: string[] };
  changelog?: { summary: string }[];
  setEntities?: { role?: string }[];
  addIncidents?: string[];
};

